// ATTENTION : JEU DE DONNÉES DE DÉMONSTRATION
// Des idées de cadeaux qui existent réellement (types de produits, d'objets et d'expériences
// disponibles dans le commerce), avec des FOURCHETTES DE PRIX INDICATIVES issues d'observations générales.
// Ce ne sont ni des offres en temps réel, ni des prix vérifiés, ni des stocks : l'interface l'affiche clairement.
// En mode connecté, chaque idée sert de « piste » : le serveur la transforme en produits réels (prix, lien, dispo).
//
// Champs : i = passions · tg = tags · y = type · tn = tons · o = originalité (1-5) · p = prix indicatif [min, max]
// a = âge [min, max] · v = affinités de personnalité · m = marchands · q = requête de recherche
// w = argument (fin de l'explication) · rel = liens autorisés · occ = occasions idéales
// own = expressions qui, si on les retrouve dans « déjà possédé », rendent l'idée redondante

const list = (s) => (s ? s.trim().split(/\s+/) : []);
function traits(spec) {
  const out = {};
  for (const t of list(spec)) out[t.slice(0, -1)] = t.endsWith('+') ? 1 : -1;
  return out;
}

function X(id, t, d, s) {
  return {
    id, t, d,
    i: list(s.i), tg: list(s.tg), y: s.y || 'objet', tn: list(s.tn), o: s.o ?? 2,
    p: s.p, a: s.a || [12, 99], v: traits(s.v), m: list(s.m || 'amazon gshop'), q: s.q || t,
    w: s.w, g: s.g || id, own: s.own ? s.own.split(',').map((x) => x.trim()) : [], rel: list(s.rel), occ: list(s.occ),
  };
}

